import {holdings,scenarios,calculate} from './model.js';
const $=s=>document.querySelector(s);let selected='higher';
const money=n=>(n<0?'−':n>0?'+':'')+new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Math.abs(n));
$('#holding-inputs').innerHTML=holdings.map((h,i)=>`<div class="holding"><div class="holding-info"><i class="dot" style="background:${h.color}"></i><div><b>${h.ticker}</b><small>${h.name}</small></div></div><div class="holding-input"><input aria-label="${h.ticker} allocation percentage" type="number" min="0" max="100" step="1" value="${h.weight}" data-holding="${i}"><span>%</span></div></div>`).join('');
const inputs=[...document.querySelectorAll('[data-holding]')];
function render(){const value=$('#value').valueAsNumber;const weights=inputs.map(el=>el.valueAsNumber);const total=weights.reduce((a,b)=>a+b,0);$('#total').textContent=Number.isFinite(total)?`${Math.round(total*100)/100}%`:'—';$('#shift').max=Number.isFinite(weights[0])?Math.max(0,weights[0]):0;$('#shift-value').textContent=$('#shift').value;$('#scenario-description').textContent=scenarios[selected].description;$('#assumptions').innerHTML=holdings.map((h,i)=>`<span>${h.ticker}: ${scenarios[selected].returns[i]>0?'+':''}${scenarios[selected].returns[i]}%</span>`).join('');
try{const result=calculate(value,weights,selected,Number($('#shift').value));$('#validation').textContent='';$('#total').className='';$('#pnl').textContent=money(result.pnl);$('#return').textContent=`${result.percent>0?'+':''}${result.percent.toFixed(2)}%`;$('#return').className=result.pnl>=0?'positive':'negative';$('#current-result').textContent=money(result.pnl);$('#after-result').textContent=money(result.after);$('#difference').textContent=result.difference===0?'No allocation change':`${money(result.difference)} vs. current`;$('#difference').className=result.difference>=0?'positive':'negative';const max=Math.max(...result.contributions.map(Math.abs),1);$('#contributions').innerHTML=holdings.filter((_,i)=>weights[i]>0).map(h=>{const i=holdings.indexOf(h),n=result.contributions[i];return `<div class="contribution"><span>${h.ticker}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.abs(n)/max*100}%;background:${n>=0?'#93aea1':'#c1a092'}"></div></div><span>${money(n)}</span></div>`}).join('');$('#calculation-status').textContent=`Updated · ${scenarios[selected].label} · ${Number($('#shift').value)} points moved from SPY to cash.`;return result;
}catch(e){$('#validation').textContent=e.message;$('#total').className='negative';for(const id of ['pnl','return','current-result','after-result'])$('#'+id).textContent='—';$('#difference').textContent='Check your inputs';$('#contributions').innerHTML='';$('#calculation-status').textContent='Calculation paused until the inputs are valid.';return null;}}
inputs.forEach(el=>el.addEventListener('input',render));$('#value').addEventListener('input',render);$('#shift').addEventListener('input',render);document.querySelectorAll('[data-scenario]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.scenario;document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));render()}));$('#reset').addEventListener('click',()=>{inputs.forEach((el,i)=>el.value=holdings[i].weight);$('#value').value=100000;$('#shift').value=0;render();$('#calculation-status').textContent='Example holdings restored. '+scenarios[selected].label+' calculated.'});render();
// The same canvas remains mounted throughout the narrative. Scroll only transforms it.
const canvas=$('#sphere'),ctx=canvas.getContext('2d'),companion=$('#companion');const motion=matchMedia('(prefers-reduced-motion: reduce)');let width=620,dpr=1,frame=0,dirty=true;const chapters=[...document.querySelectorAll('.chapter')];let positions=[];const labels=['Your world. In balance.','Different assets. Shared connections.','Signals become perspective.','Your decision. A clearer picture.'];
function measure(){dpr=Math.min(devicePixelRatio||1,2);width=innerWidth<700?420:Math.min(innerWidth*.49,760);canvas.width=width*dpr;canvas.height=width*dpr;companion.style.width=width+'px';companion.style.height=width+'px';positions=chapters.map(s=>({top:s.offsetTop,height:s.offsetHeight}));dirty=true;}measure();addEventListener('resize',measure);addEventListener('scroll',()=>{dirty=true},{passive:true});motion.addEventListener('change',()=>{dirty=true});
function position(){const mobile=innerWidth<700;const y=scrollY;let i=0;while(i<3&&y>=positions[i+1].top)i++;const p=positions[i];let t=Math.min(1,Math.max(0,(y-p.top)/p.height));t=t*t*(3-2*t);const xs=mobile?[.5,.5,.5,.5]:[.71,.27,.74,.26];const scales=mobile?[1,1.03,1.05,.96]:[1,1.28,.86,1.18];let x=xs[i],s=scales[i];if(!motion.matches&&i<3){x+=(xs[i+1]-x)*t;s+=(scales[i+1]-s)*t;}let screenY=innerHeight*.51;if(mobile)screenY=p.top+p.height*.77-y;const fade=Math.min(1,Math.max(0,($('#portfolio').offsetTop-y-innerHeight*.18)/(innerHeight*.45)));companion.style.left=x*innerWidth+'px';companion.style.top=screenY+'px';companion.style.transform=`translate(-50%,-50%) scale(${s})`;companion.style.opacity=fade;$('#orb-label').textContent=labels[i];return fade;}
function draw(time){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,width);const cx=width*.5,cy=width*.48,r=width*.282;const angle=motion.matches?.25:time*.000055;ctx.save();ctx.translate(cx,cy);
// Quiet shadow, optical atmosphere, and a pearl core.
ctx.save();ctx.translate(0,r*1.22);ctx.scale(1,.17);let shadow=ctx.createRadialGradient(0,0,0,0,0,r*1.1);shadow.addColorStop(0,'rgba(79,92,117,.20)');shadow.addColorStop(1,'rgba(79,92,117,0)');ctx.fillStyle=shadow;ctx.beginPath();ctx.arc(0,0,r*1.1,0,Math.PI*2);ctx.fill();ctx.restore();
let glow=ctx.createRadialGradient(-r*.4,-r*.5,r*.02,0,0,r);glow.addColorStop(0,'#fcfdfa');glow.addColorStop(.37,'#e6ebed');glow.addColorStop(.65,'#b5c4d4');glow.addColorStop(.82,'#879caf');glow.addColorStop(.95,'#6e8193');glow.addColorStop(1,'#d9e2e8');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();
ctx.save();ctx.beginPath();ctx.arc(0,0,r-.5,0,Math.PI*2);ctx.clip();
// Fine rotating latitude filaments give the object depth without downloaded media.
for(let j=0;j<85;j++){const lat=(j/84-.5)*Math.PI;const rr=Math.cos(lat)*r,yy=Math.sin(lat)*r;ctx.beginPath();for(let k=0;k<=130;k++){const a=k/130*Math.PI*2+angle;const x=rr*Math.cos(a),z=rr*Math.sin(a);const py=yy*.82-z*.57;const px=x*.93+yy*.15;if(k===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.strokeStyle=`rgba(246,251,254,${.15+Math.cos(lat)*.2})`;ctx.lineWidth=.6;ctx.stroke();}
const count=1400;for(let n=0;n<count;n++){const yy=1-2*n/(count-1),rr=Math.sqrt(1-yy*yy),a=n*2.399963+angle;let x=Math.cos(a)*rr,z=Math.sin(a)*rr;const ty=yy*.87-z*.49,tz=yy*.49+z*.87;if(tz<0)continue;const light=(x*-.4+ty*-.5+tz)*.5+.5;ctx.fillStyle=`rgba(${light>.7?'250,253,255':'62,85,115'},${.12+tz*.28})`;ctx.beginPath();ctx.arc(x*r,ty*r,.45+tz*.35,0,6.29);ctx.fill();}ctx.restore();
// Orbital paths remain recognizably attached to the companion in every chapter.
for(let o=0;o<3;o++){ctx.save();ctx.rotate(-.57+o*.055);ctx.beginPath();ctx.ellipse(0,0,r*(1.5+o*.08),r*(.44+o*.045),0,0,Math.PI*2);ctx.strokeStyle=o===1?'rgba(118,140,170,.44)':'rgba(143,159,181,.2)';ctx.lineWidth=o===1?.85:.55;ctx.stroke();if(o===1){let a=angle*2+.4;let ox=Math.cos(a)*r*1.58,oy=Math.sin(a)*r*.485;ctx.fillStyle='#6f89bd';ctx.beginPath();ctx.arc(ox,oy,3,0,6.29);ctx.fill();}ctx.restore();}
ctx.restore();}
let last=0;function tick(time){const visible=dirty?position():Number(companion.style.opacity||1);if(visible>0&&(!motion.matches||dirty)&&time-last>32){draw(time);last=time;dirty=false;}frame=requestAnimationFrame(tick);}frame=requestAnimationFrame(tick);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelAnimationFrame(frame);else{dirty=true;frame=requestAnimationFrame(tick)}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_portfolio_scenario',description:'Read the current illustrative portfolio scenario and calculation. Does not modify holdings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({scenario:selected,illustrative:true,result:render()})})).catch(()=>{});}catch{}}
